package foodchain

import "strings"

var animals = []struct {
	name    string
	comment string
}{
	{"fly", ""},
	{"spider", "It wriggled and jiggled and tickled inside her."},
	{"bird", "How absurd to swallow a bird!"},
	{"cat", "Imagine that, to swallow a cat!"},
	{"dog", "What a hog, to swallow a dog!"},
	{"goat", "Just opened her throat and swallowed a goat!"},
	{"cow", "I don't know how she swallowed a cow!"},
	{"horse", "She's dead, of course!"},
}

func Verse(v int) string {
	var b strings.Builder
	a := animals[v-1]
	b.WriteString("I know an old lady who swallowed a " + a.name + ".\n")
	if a.comment != "" {
		b.WriteString(a.comment + "\n")
	}
	if v < 8 {
		for i := v - 1; i >= 1; i-- {
			prev := animals[i]
			if prev.name == "spider" {
				b.WriteString("She swallowed the " + a.name + " to catch the spider that wriggled and jiggled and tickled inside her.\n")
			} else {
				b.WriteString("She swallowed the " + a.name + " to catch the " + prev.name + ".\n")
			}
		}
		b.WriteString("I don't know why she swallowed the fly. Perhaps she'll die.")
	}
	return b.String()
}

func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, 8)
}

